let sourceText='', profileAnalysis={};
let currentProfileStatus='draft', lastOverview=null, lastReport=null;
const $=id=>document.getElementById(id);
const fields=['jobs','adjacent_jobs','metiers_vises','locations','remote','contracts','sectors','exclusions','skills','sources','seniorite'];
const SKILL_LEVELS=['débutant','opérationnel','confirmé','expert','à confirmer'];
function message(text,kind='ok'){const n=$('notice');n.textContent=text;n.className='notice '+kind;n.hidden=false;setTimeout(()=>n.hidden=true,4500)}
function split(value){return value.split(/[\n,]+/).map(x=>x.trim()).filter(Boolean)}
function renderCvContext(data){const has=!!(data.main_job||data.secondary_job||data.profile_summary);$('main_job').value=data.main_job||'';$('secondary_job').value=data.secondary_job||'';$('profile_summary').value=data.profile_summary||'';$('cvContext').hidden=!has}
const WEIGHT_DIMS=[['competences','Compétences'],['intitule','Métier & missions'],['experience','Expérience / séniorité'],['localisation','Localisation & remote'],['salaire','Salaire'],['contrat','Type de contrat'],['secteur','Secteur']];
const DEFAULT_WEIGHTS={competences:35,intitule:15,experience:10,localisation:15,salaire:10,contrat:10,secteur:5};
let weights={...DEFAULT_WEIGHTS};
function renderWeights(){const list=$('weightsList');list.innerHTML=WEIGHT_DIMS.map(([k,label])=>`<label class="weight"><span>${label}</span><input id="w_${k}" type="range" min="0" max="100" step="1" value="${weights[k]}" oninput="weightChange('${k}',this.value)"><em id="w_${k}_v">${weights[k]} %</em></label>`).join('');updateWeightTotal()}
function weightChange(k,v){weights[k]=Math.max(0,Math.min(100,Number(v)));const em=$('w_'+k+'_v');if(em)em.textContent=weights[k]+' %';updateWeightTotal()}
function updateWeightTotal(){const total=WEIGHT_DIMS.reduce((s,[k])=>s+weights[k],0);$('weightsTotal').textContent=total.toFixed(0)+' %';const st=$('weightsStatus');const ok=Math.abs(total-100)<0.6;st.textContent=ok?'✓':'✕';st.className=ok?'ok':'bad';st.title=ok?'Somme à 100 %':`Somme : ${total.toFixed(1)} %`}
function resetWeights(){weights={...DEFAULT_WEIGHTS};WEIGHT_DIMS.forEach(([k])=>{const el=$('w_'+k);if(el)el.value=weights[k];const em=$('w_'+k+'_v');if(em)em.textContent=weights[k]+' %'});updateWeightTotal();message('Pondérations remises aux valeurs par défaut.')}
function normalizeWeights(){const total=WEIGHT_DIMS.reduce((s,[k])=>s+weights[k],0);if(total<=0)return weights={...DEFAULT_WEIGHTS};const scale=100/total;WEIGHT_DIMS.forEach(([k])=>{weights[k]=Math.round(weights[k]*scale)});const rem=100-WEIGHT_DIMS.reduce((s,[k])=>s+weights[k],0);if(rem)weights[WEIGHT_DIMS[0][0]]+=rem;WEIGHT_DIMS.forEach(([k])=>{const el=$('w_'+k);if(el)el.value=weights[k];const em=$('w_'+k+'_v');if(em)em.textContent=weights[k]+' %'});updateWeightTotal();message('Pondérations normalisées à 100 %.')}
function loadWeights(p){if(!p)p={};const f=p.ponderation||p.weights||{};WEIGHT_DIMS.forEach(([k])=>{weights[k]=f[k]!=null?Math.round(Number(f[k])*100):DEFAULT_WEIGHTS[k]});if(typeof renderWeights==='function')renderWeights()}
function weightsPayload(){const out={};WEIGHT_DIMS.forEach(([k])=>{out[k]=(weights[k]||0)/100});return out}
async function api(url,options={}){const headers={...(options.headers||{})};const tok=localStorage.getItem('jw_token');if(tok&&!headers.Authorization)headers.Authorization='Bearer '+tok;const r=await fetch(url,{...options,headers});let data=null;try{data=await r.json()}catch(e){data=null}if(r.status===401){updateAuthGate(null,true);throw new Error((data&&data.detail)||'Connectez-vous pour continuer.')}if(!r.ok)throw new Error((data&&data.detail)||'Une erreur est survenue.');return data}
async function authMe(){try{const r=await fetch('/api/auth/me',{headers:localStorage.getItem('jw_token')?{Authorization:'Bearer '+localStorage.getItem('jw_token')}:{}});return await r.json()}catch(e){return{user:null,auth:true}}}
function updateAuthGate(me,forceGate){const gate=$('authGate');const main=$('appMain');const bar=$('authBar');const needGate=forceGate||(me&&me.auth!==false&&!me.user);if(gate)gate.hidden=!needGate;if(main)main.hidden=!!needGate;if(bar){const showBar=!needGate;bar.hidden=!showBar;if(showBar)$('authState').textContent=me&&me.user?('Connecté : '+me.user.username):'Mode mono-utilisateur'}return!needGate}
async function doLogin(mode){const u=$('authUser').value.trim();const p=$('authPass').value;if(!u||!p){authMessage('Saisissez un nom et un mot de passe.','error');return}try{const r=await fetch('/api/auth/'+mode,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:u,password:p})});const data=await r.json();if(!r.ok)throw new Error(data.detail||'Échec.');localStorage.setItem('jw_token',data.token);boot();message(mode==='register'?'Compte créé, bienvenue '+data.username+' !':'Connecté en tant que '+data.username+'.')}catch(e){authMessage(e.message,'error')}}
function authMessage(text,kind){const n=$('noticeAuth')||$('notice');n.textContent=text;n.className='notice '+kind;n.hidden=false;setTimeout(()=>n.hidden=true,4500)}
async function doLogout(){try{await api('/api/auth/logout',{method:'POST'})}catch(e){}localStorage.removeItem('jw_token');location.reload()}
async function showAuth(force){let me={user:null,auth:true};if(!force){try{me=await authMe()}catch(e){me={user:null,auth:true}}}const gate=$('authGate');if(gate&&$('authPass')){if(force&&gate.hidden)gate.hidden=false;if(!gate.hidden)setTimeout(()=>{const el=$('authUser');if(el)el.focus()},50)}return updateAuthGate(me,force)}
async function boot(){let me={user:null,auth:true};try{me=await authMe()}catch(e){me={user:null,auth:true}}const ok=updateAuthGate(me,false);if(!ok)return;bindJobFilters();renderWeights();Promise.all([loadProfile(),loadOverview(),loadJobs(),loadApplications()]).then(()=>showTab(currentProfileStatus==='validated'?'tracking':'profile')).catch(e=>message(e.message,'error'))}
function showTab(name){document.querySelectorAll('.tab,.panel').forEach(x=>x.classList.remove('active'));const btn=document.querySelector(`.tab[data-tab="${name}"]`);if(btn)btn.classList.add('active');const panel=$(name);if(panel)panel.classList.add('active');autoSizeDossierTextareas();if(name==='tracking')loadKanban()}
document.querySelectorAll('.tab').forEach(button=>button.onclick=()=>showTab(button.dataset.tab));
// Textareas de la page candidature (dossier) : hauteur automatique selon le
// contenu, sans jamais descendre sous la hauteur initiale liée à l'attribut rows.
function autoSizeTextarea(el){if(!el||el.tagName!=='TEXTAREA'||!el.clientHeight)return;if(!el.dataset.autosizeFloor)el.dataset.autosizeFloor=String(el.clientHeight);el.style.height='auto';el.style.height=(Math.max(el.scrollHeight,Number(el.dataset.autosizeFloor))+(el.offsetHeight-el.clientHeight))+'px'}
function autoSizeDossierTextareas(){document.querySelectorAll('#dossierView textarea').forEach(autoSizeTextarea)}
document.addEventListener('input',e=>{if(e.target&&e.target.matches&&e.target.matches('#dossierView textarea'))autoSizeTextarea(e.target)});
window.addEventListener('resize',autoSizeDossierTextareas);
async function loadProfile(){const p=await api('/api/profile');sourceText=p.source_text||'';profileAnalysis=p.data||{};applyProfileData(profileAnalysis,p.name||'');setProfileStatus(p.status)}
// Remplit la fiche à partir d'une analyse (CV importé ou affinage IA) : tous les
// champs du profil sont exposés, y compris secteurs, exclusions et salaires.
function applyProfileData(data,fallbackName=''){data=data||{};$('name').value=data.name||fallbackName||$('name').value||'';fields.forEach(k=>{const el=$(k);if(el)el.value=(data[k]||[]).join('\n')});$('jobs').value=[data.main_job,...(data.jobs||[]).filter(j=>j!==data.main_job&&j!==data.secondary_job)].concat(data.secondary_job?[data.secondary_job]:[]).filter(Boolean).join('\n');$('mobility').value=data.mobility||'';$('profile_summary').value=data.profile_summary||'';$('years_experience').value=data.years_experience??'';$('salary_min').value=data.salary_min??'';$('salary_max').value=data.salary_max??'';renderCvContext(data);renderMatrix();loadWeights(data)}
function setProfileStatus(status){currentProfileStatus=status;const ready=status==='validated';$('profileStatus').textContent=ready?'Validé':'À préparer';$('profileBadge').textContent=ready?'Profil validé':'Brouillon';$('profileBadge').className='badge '+(ready?'ready':'');const tabLabel=$('profileTabLabel');if(tabLabel)tabLabel.textContent=ready?'Profil · validé':'Profil · à préparer'}
// La matrice est la source unique du détail (catégorie, niveau, preuve) : la
// liste « Compétences » est sa projection plate. Toute compétence ajoutée à la
// main reçoit une ligne dédiée, toute ligne supprimée disparaît.
function syncSkillMatrix(skills,matrix){const norm=v=>String(v||'').trim().toLowerCase();const kept=(matrix||[]).filter(r=>r&&r.skill&&skills.some(s=>norm(s)===norm(r.skill)));const known=new Set(kept.map(r=>norm(r.skill)));skills.forEach(s=>{if(!known.has(norm(s))){kept.push({skill:s,category:'Autre',level:'à confirmer',evidence:'À confirmer dans le CV'});known.add(norm(s))}});return kept}
function payload(validated){const data={name:profileAnalysis.name||'',main_job:profileAnalysis.main_job||'',secondary_job:profileAnalysis.secondary_job||'',mobility:$('mobility').value.trim(),years_experience:$('years_experience').value?Number($('years_experience').value):null,salary_min:$('salary_min').value?Number($('salary_min').value):null,salary_max:$('salary_max').value?Number($('salary_max').value):null,skill_matrix:syncSkillMatrix(split($('skills').value),profileAnalysis.skill_matrix||[]),profile_summary:$('profile_summary').value.trim(),ponderation:weightsPayload()};fields.forEach(k=>data[k]=split($(k).value));return {name:$('name').value.trim()||'Candidat',data,validate_profile:validated,source_text:sourceText}}
async function saveProfile(event,validated){if(event)event.preventDefault();const btn=event?event.submitter||document.querySelector('#profileForm button'):null;const idle=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent=validated?'Validation en cours…':'Enregistrement…'}try{const p=await api('/api/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload(validated))});setProfileStatus(p.status);message(validated?'Profil validé : la veille et le scoring sont disponibles.':'Profil enregistré. Complétez-le puis validez-le.');loadOverview();if(validated)loadJobs()}catch(e){message(e.message,'error')}finally{if(btn){btn.disabled=false;btn.textContent=idle}}}
// Matrice regroupée par domaine : chaque ligne expose le niveau (modifiable) et
// la preuve tirée du CV, pour que l'utilisateur voie tout ce qui a été extrait.
function renderMatrix(){const el=$('skillMatrix'),summary=$('matrixSummary');const matrix=profileAnalysis.skill_matrix||[];if(summary)summary.textContent=matrix.length?`Matrice de compétences (${matrix.length})`:'Matrice de compétences détectées';if(!el)return;if(!matrix.length){el.innerHTML='<p class="hint">Aucune compétence détectée pour le moment.</p>';return}const groups=[];matrix.forEach((row,i)=>{const cat=row.category||'Autre';let g=groups.find(x=>x.category===cat);if(!g){g={category:cat,rows:[]};groups.push(g)}g.rows.push({row,i})});el.innerHTML=groups.map(g=>`<section class="matrix-group"><h4>${safe(g.category)} <span class="matrix-count">${g.rows.length}</span></h4>${g.rows.map(({row,i})=>`<div class="matrix-row"><div class="matrix-line"><strong>${safe(row.skill)}</strong><select class="select matrix-level" aria-label="Niveau de ${safe(row.skill)}" onchange="setMatrixField(${i},'level',this.value)">${SKILL_LEVELS.map(l=>`<option value="${l}" ${l===row.level?'selected':''}>${l}</option>`).join('')}</select><input class="matrix-category" value="${safe(row.category||'')}" aria-label="Catégorie de ${safe(row.skill)}" onchange="setMatrixField(${i},'category',this.value)"></div><small>${safe(row.evidence)}</small></div>`).join('')}</section>`).join('')}
function setMatrixField(index,field,value){const row=(profileAnalysis.skill_matrix||[])[index];if(!row)return;row[field]=value;if(field==='category')renderMatrix()}
async function importCv(){const file=$('cvFile').files[0];if(!file)return;const label=document.querySelector('.dropzone strong');label.textContent=file.name;const fd=new FormData();fd.append('file',file);$('cvResult').className='analysis';$('cvResult').textContent='Analyse du CV en cours…';agentFeedStart('Import du CV');try{const r=await streamPost('/api/cv/import/stream',{method:'POST',body:fd},evt=>{if(evt.type==='progress')agentFeedStep(evt.message)});agentFeedStep('Analyse prête : vérifiez les champs avant validation.','done');agentFeedFinish();sourceText=r.source_text;profileAnalysis=r.data;applyProfileData(r.data);$('cvResult').innerHTML='<strong>Analyse prête ('+safe(r.analysis.provider)+')</strong><br>'+safe(r.data.profile_summary||'Vérifiez les informations extraites.')+'<br><small>'+safe(r.note)+'</small>';message('CV analysé. Vérifiez les champs et la matrice avant validation.')}catch(e){agentFeedStep(e.message,'error');agentFeedFinish('error');$('cvResult').className='analysis empty';$('cvResult').textContent=e.message;message(e.message,'error')}}
async function aiRefineProfile(btn){const promptEl=$('profileAiPrompt');const instruction=promptEl?promptEl.value.trim():'';if(!instruction){message('Écrivez une consigne pour l’IA avant de lancer l’affinage.','error');return}const status=$('profileAiStatus');const idle=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent='Affinage IA…'}if(status)status.textContent='L’IA applique votre consigne à la fiche (CV comme seule base factuelle)…';try{const body={instruction,name:$('name').value.trim()||'Candidat',data:payload(false).data,source_text:sourceText};const r=await api('/api/profile/refine',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});profileAnalysis=r.data||{};applyProfileData(profileAnalysis,r.data?.name||'');if(status)status.textContent=[r.changes_summary,r.warning||(r.applied?'Fiche mise à jour : relisez puis enregistrez ou validez.':'')].filter(Boolean).join(' ');message(r.applied?'Fiche affinée par l’IA — relisez puis enregistrez ou validez.':'Affinage IA sans effet : '+(r.warning||'aucune modification'),r.applied?'ok':'error')}catch(e){if(status)status.textContent='';message(e.message,'error')}finally{if(btn){btn.disabled=false;btn.textContent=idle}}}
function busy(btn,on,text){if(!btn)return;btn.disabled=on;btn.textContent=on?text:btn.dataset.idle||'Lancer une campagne'}
async function streamPost(url,options,onEvent){options=options||{};const headers={...(options.headers||{})};const tok=localStorage.getItem('jw_token');if(tok&&!headers.Authorization)headers.Authorization='Bearer '+tok;const r=await fetch(url,{...options,headers});const ct=(r.headers.get('content-type')||'');if(!r.ok){let msg='Une erreur est survenue.';if(ct.includes('application/json')){try{msg=(await r.json()).detail||msg}catch(x){}}if(r.status===401)updateAuthGate(null,true);throw new Error(msg)}if(!ct.includes('text/event-stream')||!r.body){const data=await r.json();onEvent({type:'done',result:data});return data}const reader=r.body.getReader();const dec=new TextDecoder();let buf='',result=null,fail=null;const frame=f=>f.split('\n').forEach(line=>{if(!line.startsWith('data:'))return;try{const evt=JSON.parse(line.slice(5).trim());if(evt.type==='done')result=evt.result;else if(evt.type==='error')fail=new Error(evt.message||'Une erreur est survenue.');onEvent(evt)}catch(x){}});for(;;){const {done,value}=await reader.read();if(done)break;buf+=dec.decode(value,{stream:true});let i;while((i=buf.indexOf('\n\n'))>=0){frame(buf.slice(0,i));buf=buf.slice(i+2)}}if(buf.trim())frame(buf);if(fail)throw fail;return result}
let agentHideTimer=null;
function agentFeedStart(title){clearTimeout(agentHideTimer);const f=$('agentFeed');f.hidden=false;f.classList.remove('done','error');$('agentFeedTitle').textContent=title;$('agentFeedSteps').innerHTML='';agentFeedStep('Opération démarrée…')}
function agentFeedStep(text,state='current'){const steps=$('agentFeedSteps');const prev=steps.querySelector('li.current');if(prev){prev.classList.remove('current');prev.classList.add('done')}const li=document.createElement('li');li.className=state;li.textContent=text;steps.appendChild(li);steps.scrollTop=steps.scrollHeight}
function agentFeedFinish(state='done'){const f=$('agentFeed');f.classList.add(state);clearTimeout(agentHideTimer);agentHideTimer=setTimeout(()=>{f.hidden=true},state==='error'?10000:6000)}
function closeAgentFeed(){clearTimeout(agentHideTimer);$('agentFeed').hidden=true}
async function runCampaign(){const btn=$('campaignBtn');btn.dataset.idle='Lancer une campagne';busy(btn,true,'Veille en cours…');const src=$('campaignSource').value;agentFeedStart('Campagne · '+src);try{const r=await streamPost('/api/campaign/run/stream?source='+src,{method:'POST'},evt=>{if(evt.type==='progress')agentFeedStep(evt.message,evt.step==='source_error'?'error':'current')});agentFeedStep(`Terminé : ${r.imported} nouvelle(s) · ${r.shortlisted} à examiner.`,'done');agentFeedFinish();busy(btn,false);message(`Campagne (${src}) : ${r.imported} nouvelle(s) · ${r.processed} au total · ${r.shortlisted} à examiner.`);renderCampaignReport(r);renderMarketAnalysis(r.market_analysis);loadOverview();loadJobs();showTab('market')}catch(e){busy(btn,false);agentFeedStep(e.message,'error');agentFeedFinish('error');message(e.message,'error');showTab(currentProfileStatus==='validated'?'market':'profile')}}
function renderCampaignReport(r){
 const box=$('campaignReport');if(!r||!r.report){box.hidden=true;return}
 const s=r.report.sources||{}; const rows=Object.entries(s).map(([k,v])=>`<div><strong>${safe(k)}</strong><span class="${v.error?'error':'ok'}">${v.count||0} offre(s)${v.error?' · '+safe(v.error):''}</span></div>`).join('')
 box.hidden=false;box.innerHTML=`<h3>Résultat de la veille (${safe(r.source)})</h3><div class="report-grid">${rows||'<div>Aucune source exécutée.</div>'}</div><small>${r.report.total_raw||0} brut(s) → ${r.report.total_unique||0} unique(s).</small>`
}
/* Ajout d'une annonce repérée soi-même : le lien est collé, la plateforme fait le
   reste (récupération, pré-notation, complétion, notation) et l'ajoute à la liste. */
function importUrlPayload(){const val=id=>{const el=$(id);return el?(el.value||'').trim():''};return {url:val('importUrl'),title:val('importTitle'),company:val('importCompany'),description:val('importDescription')}}
function importUrlReport(r){
 const rep=(r&&r.report)||{},j=(r&&r.job)||{};
 const rows=[['Intitulé',j.title],['Entreprise',j.company],['Lieu',j.location],['Contrat',j.contract],['Télétravail',j.remote],['Salaire',fmtSal(j.salary_min,j.salary_max)],['Source',rep.source],['Pré-note',rep.prescore!=null?rep.prescore+'/10':''],['Note finale',rep.score!=null?rep.score+'/10':''],['Extraction',(rep.extraction||[]).join(', ')]].filter(([,v])=>String(v==null?'':v).trim());
 const grid=rows.map(([k,v])=>`<div><strong>${safe(k)}</strong><span class="ok">${safe(v)}</span></div>`).join('');
 const matched=(rep.matched_skills||[]).length?`<small class="hint">Compétences communes avec le profil : ${safe(rep.matched_skills.join(', '))}.</small>`:'';
 const gaps=(rep.gaps||[]).length?`<small class="hint">Demandé par l'annonce, absent du profil : ${safe(rep.gaps.join(', '))}.</small>`:'';
 const warn=(rep.warnings||[]).map(s=>`<small class="warning">${safe(s)}</small>`).join('');
 const link=j.url?`<a class="ghost link-btn" href="${safe(j.url)}" target="_blank" rel="noopener">Ouvrir l'annonce ↗</a>`:'';
 return `<h3>${rep.created?'Annonce ajoutée à la liste':'Annonce mise à jour'}</h3><div class="report-grid">${grid}</div>${matched}${gaps}${warn}<div class="form-actions spaced">${link}</div>`
}
async function importOfferUrl(){
 const payload=importUrlPayload();const btn=$('importUrlBtn');const box=$('importUrlResult');
 if(!payload.url){message('Collez le lien de l’annonce avant de lancer l’import.','error');return}
 const idle=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent='Récupération…'}
 if(box){box.hidden=false;box.className='analysis';box.textContent='Récupération de la page, pré-notation et notation de l’annonce…'}
 agentFeedStart('Annonce par lien');
 try{
  const r=await streamPost('/api/jobs/import-url/stream',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)},evt=>{if(evt.type==='progress')agentFeedStep(evt.message)});
  const rep=(r&&r.report)||{};
  agentFeedStep(`Annonce ${rep.created?'ajoutée':'mise à jour'} — note ${rep.score}/10.`,'done');agentFeedFinish();
  if(box){box.className='analysis';box.innerHTML=importUrlReport(r)}
  $('importUrl').value='';
  message(`Annonce ${rep.created?'ajoutée':'mise à jour'} : ${(r.job||{}).title||''} — note ${rep.score}/10.`);
  await Promise.all([loadJobs(),loadOverview()]);
  showTab('market')
 }catch(e){
  agentFeedStep(e.message,'error');agentFeedFinish('error');
  if(box){box.className='analysis empty';box.textContent=e.message}
  message(e.message,'error')
 }finally{if(btn){btn.disabled=false;btn.textContent=idle}}
}
function renderMarketAnalysis(a){
 const box=$('marketAnalysis');if(!a){box.hidden=true;return}
 const kw=(a.keywords||[]).map(s=>'<span>'+safe(s)+'</span>').join('')
 const sr=(a.seniorities||[]).map(s=>'<span>'+safe(s)+'</span>').join('')
 const ang=(a.angles||[]).map(s=>'<li>'+safe(s)+'</li>').join('')
 const hyp=(a.hypotheses||[]).map(s=>'<li>'+safe(s)+'</li>').join('')
 box.hidden=false;box.innerHTML=`<h3>Analyse du marché</h3><p>${safe(a.summary||'')}</p>`+(kw?`<div class="chips">${kw}</div>`:'')+(sr?`<div class="chips">${sr}</div>`:'')+(ang?`<ul><b>Pistes :</b>${ang}</ul>`:'')+(hyp?`<ul class="warning"><b>Hypothèses (à confirmer) :</b>${hyp}</ul>`:'')
}
async function loadOverview(){const o=await api('/api/overview');lastOverview=o;$('jobsCount').textContent=o.jobs_count;$('shortlistCount').textContent=o.retained_count;$('applicationsCount').textContent=o.applications_count;setProfileStatus(o.profile_status);renderTrackingTodo();const topSkill=(o.market.skills||[]).map(([skill])=>String(skill).trim()).find(skill=>skill.length>2&&/[a-zà-ÿ]/i.test(skill));$('marketSummary').textContent=topSkill?`Compétence la plus demandée sur le marché analysé : ${topSkill}.`:'Les données du marché sont prêtes à être explorées.'}
function safe(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fmtSal(min,max){const e=n=>n?Math.round(n).toLocaleString('fr-FR')+' €':'';
  if(min&&max)return e(min)+' – '+e(max);if(min)return 'dès '+e(min);if(max)return 'jusqu’à '+e(max);return ''}
/* --------------------------------------- offre : dates, source, explication */
const SOURCE_LABELS={france_travail:'France Travail',adzuna:'Adzuna',linkedin:'LinkedIn',indeed:'Indeed',wttj:'Welcome to the Jungle',apec:'APEC',hellowork:'HelloWork',demo:'Jeu de démonstration',file:'Fichier local'};
const DECISION_LABELS={new:'Nouvelle',retained:'Retenue',ignored:'Ignorée'};
const DIM_LABELS={competences:'Compétences',intitule:'Métier & missions',experience:'Expérience / séniorité',localisation:'Localisation & remote',contrat:'Type de contrat',salaire:'Salaire',secteur:'Secteur'};
function parseDate(iso){if(!iso)return null;const d=new Date(String(iso).replace(/(\.\d{3})\d+/,'$1'));return isNaN(d)?null:d}
function fmtDate(iso,withTime){const d=parseDate(iso);if(!d)return '';return d.toLocaleDateString('fr-FR',withTime?{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}:{day:'2-digit',month:'2-digit',year:'numeric'})}
function fmtDateTime(iso){return fmtDate(iso,true)}
function sourceLabel(j){const s=j.explanation?.source;return SOURCE_LABELS[s]||s||''}
function toggleDetails(id){const el=$('details_'+id);if(!el)return;el.hidden=!el.hidden;const btn=document.querySelector('[data-toggle-details="'+id+'"]');if(btn){btn.setAttribute('aria-expanded',String(!el.hidden));btn.textContent=el.hidden?'Voir les détails':'Masquer les détails'}}
function scoreBreakdown(j){const e=j.explanation||{};const dims=e.dimensions||{};const keys=Object.keys(dims);if(!keys.length)return '';const weights=e.weights||{};const rows=keys.map(k=>{const value=Number(dims[k])||0;const weight=Math.round((Number(weights[k])||0)*100);return `<div class="score-dim"><span class="score-dim-label">${safe(DIM_LABELS[k]||k)}<em>${weight} %</em></span><span class="score-bar" aria-hidden="true"><i style="width:${Math.max(0,Math.min(100,value*10))}%"></i></span><b>${value.toFixed(1)}</b></div>`}).join('');const gaps=(e.gaps||[]).slice(0,8);const indexAbsent=e.competences_source==='absente';const indexNote=indexAbsent?'<p class="hint">Compétences non indexées dans cette annonce : la dimension « Compétences » est neutralisée (5/10) au lieu d’être mise à zéro.</p>':'';const prescore=Number(e.prescore);const note=!isNaN(prescore)&&prescore>0?`<p class="hint">Pré-note heuristique avant complétion : ${prescore.toFixed(1)}/10.</p>`:'';const engine=e.scorer==='jev'?`<p class="hint">Dimensions notées par Jev (TypeSafe)${e.jev&&e.jev.model?' — '+safe(e.jev.model):''} ; les dimensions non évaluables sont omises et leur poids redistribué.</p>`:e.jev_error?`<p class="hint">Jev indisponible (${safe(e.jev_error)}) : note heuristique.</p>`:'';return `<details class="details-block"><summary>Comment la note est calculée</summary><div class="score-breakdown">${rows}</div>${engine}${gaps.length?`<p class="hint">Compétences demandées absentes du profil : ${safe(gaps.join(', '))}.</p>`:''}${indexNote}${note}</details>`}
function jobReason(j){const e=j.explanation||{};const gates=e.gates||{};const blocked=Object.keys(gates).filter(k=>gates[k]===false);const parts=[];if(blocked.length)parts.push(`<b class="reason-warn">Point bloquant : ${safe(blocked.join(', '))}</b> — note plafonnée à 3,9/10.`);const strengths=(e.strengths||[]).slice(0,5);if(strengths.length)parts.push('Compétences communes : '+safe(strengths.join(', '))+'.');const prescore=Number(e.prescore);if(!isNaN(prescore)&&prescore>0&&j.score!=null)parts.push(`Pré-note ${prescore.toFixed(1)} → note finale ${Number(j.score).toFixed(1)}/10.`);return parts.length?`<p class="job-reason">${parts.join(' ')}</p>`:''}
/* Le détail ne répète jamais ce qui est déjà visible dans la carte (entreprise, lieu,
   contrat, salaire, source, date) : il apporte l'information complémentaire. */
function detailBlock(j){const rows=[['Secteurs',(j.sectors||[]).join(', ')],['Identifiant source',j.external_id]];const lis=rows.filter(([,v])=>v).map(([k,v])=>`<li><strong>${safe(k)}</strong><span>${safe(v)}</span></li>`).join('');const skills=(j.skills||[]).map(s=>'<span class="skill">'+safe(s)+'</span>').join('');return `<div class="job-detail-body">${j.description?`<p class="job-description">${safe(j.description)}</p>`:'<p class="hint">Description absente dans la source.</p>'}${skills?'<div class="chips">'+skills+'</div>':''}<ul class="detail-list">${lis}</ul></div>${scoreBreakdown(j)}`}

async function decide(id,value){try{await api(`/api/jobs/${id}/decision?value=${value}`,{method:'POST'});loadJobs();loadOverview()}catch(e){message(e.message,'error')}}
/* ----------------------------------------------- liste des opportunités */
function jobCard(j){const sal=fmtSal(j.salary_min,j.salary_max);const skillChips=(j.skills||[]).slice(0,6).map(s=>'<span class="skill">'+safe(s)+'</span>').join('');const appBadge=j.has_application?`<span class="badge" title="Un dossier de candidature existe pour cette offre">Dossier #${j.application_id}</span>`:'';const dimensions=j.explanation?.dimensions||{};const hasDetails=Boolean(j.description||(j.skills||[]).length||Object.keys(dimensions).length);const meta=[['Entreprise',j.company],['Lieu',j.location],['Télétravail',j.remote],['Contrat',j.contract],['Salaire',sal],['Source',sourceLabel(j)],['Ajoutée le',fmtDate(j.created_at)]].filter(([,v])=>v).map(([k,v])=>`<div><dt>${safe(k)}</dt><dd>${safe(v)}</dd></div>`).join('');const toggle=j.decision==='ignored'?`<button type="button" class="ghost" onclick="decide(${j.id},'new')">Réactiver</button>`:`<button type="button" class="ghost" onclick="decide(${j.id},'ignored')">Ignorer</button>`;const detailsBtn=hasDetails?`<button type="button" class="ghost details-toggle" data-toggle-details="${j.id}" aria-expanded="false" onclick="toggleDetails(${j.id})">Voir les détails</button>`:'';const linkBtn=j.url?`<a class="ghost link-btn" href="${safe(j.url)}" target="_blank" rel="noopener">Ouvrir l'annonce ↗</a>`:'';const primary=j.has_application?`<button type="button" class="primary" onclick="openDossier(${j.application_id},true)">Ouvrir le dossier</button>`:j.decision==='retained'?`<button type="button" class="primary" onclick="createApplication(${j.id},this)">Candidater</button>`:`<button type="button" class="primary" onclick="decide(${j.id},'retained')">Retenir</button>`;return `<article class="job"><div class="score">${j.score??'—'}<small>/10</small></div><div class="job-body"><div class="job-main"><div class="job-title"><h3>${safe(j.title)}</h3><span class="decision ${safe(j.decision)}">${safe(DECISION_LABELS[j.decision]||j.decision)}</span>${appBadge}</div><dl class="job-meta">${meta}</dl>${skillChips?'<div class="chips">'+skillChips+'</div>':''}${jobReason(j)}</div><div class="actions">${toggle}${detailsBtn}${linkBtn}${primary}</div></div>${hasDetails?`<div class="job-details" id="details_${j.id}" hidden>${detailBlock(j)}</div>`:''}</article>`}
function renderJobs(){const jobs=filteredJobs.slice(0,visibleJobs);const cards=jobs.map(jobCard).join('');const more=filteredJobs.length>visibleJobs?`<div class="jobs-footer"><button type="button" class="ghost" onclick="showMoreJobs()">Afficher 30 offres de plus</button></div>`:'';$('jobList').innerHTML=cards?cards+more:'<div class="empty">Aucune offre ne correspond à ces filtres. Baissez le score minimum ou réinitialisez les filtres.</div>';updateJobsCount(jobs.length)}
let allJobs=[];let filteredJobs=[];let visibleJobs=30;let jobFilterTimer=null;
function jobsFilterState(){return{minScore:Number($('minScore')?.value||0)||0,decision:$('decisionFilter')?.value||'',application:$('applicationFilter')?.value||'',sort:$('sortFilter')?.value||'score'}}
function sortJobs(list){const mode=jobsFilterState().sort;const copy=[...list];if(mode==='date')return copy.sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));if(mode==='title')return copy.sort((a,b)=>String(a.title||'').localeCompare(String(b.title||''),'fr'));return copy.sort((a,b)=>(b.score??-1)-(a.score??-1))}
function updateJobsCount(shown){const box=$('jobsFilterCount');if(!box)return;const f=jobsFilterState();const best=allJobs.reduce((m,j)=>Math.max(m,j.score??0),0);const active=[];if(f.minScore)active.push('score ≥ '+f.minScore);if(f.decision)active.push('décision : '+(DECISION_LABELS[f.decision]||f.decision));if(f.application)active.push(f.application==='yes'?'avec dossier':'sans dossier');const parts=[`${shown} affichée(s) sur ${allJobs.length} en base`,active.length?'filtres actifs — '+active.join(', '):'aucun filtre actif'];if(f.minScore>best)parts.push(`score le plus élevé en base : ${best.toFixed(1)}/10`);box.hidden=false;box.textContent=parts.join(' · ')}
function applyJobFilters(){const f=jobsFilterState();filteredJobs=sortJobs(allJobs.filter(j=>{if(f.minScore&&(j.score??0)<f.minScore)return false;if(f.decision&&j.decision!==f.decision)return false;if(f.application==='yes'&&!j.has_application)return false;if(f.application==='no'&&j.has_application)return false;return true}));visibleJobs=30;renderJobs()}
function resetJobFilters(){[['minScore','0'],['decisionFilter',''],['applicationFilter',''],['sortFilter','score']].forEach(([id,v])=>{const el=$(id);if(el)el.value=v});applyJobFilters();message('Filtres réinitialisés.')}
function bindJobFilters(){['minScore','decisionFilter','applicationFilter','sortFilter'].forEach(id=>{const el=$(id);if(!el)return;const live=id==='minScore';el.addEventListener(live?'input':'change',()=>{clearTimeout(jobFilterTimer);jobFilterTimer=setTimeout(applyJobFilters,live?180:0)})})}
function showMoreJobs(){visibleJobs+=30;renderJobs()}
async function loadJobs(){try{allJobs=await api('/api/jobs')}catch(e){message(e.message,'error');allJobs=[]}applyJobFilters()}
async function createApplication(jobId,btn){const idle=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent='Candidature…'}agentFeedStart('Candidature');try{const r=await streamPost('/api/applications/candidater/stream?job_id='+jobId,{method:'POST'},evt=>{if(evt.type==='progress')agentFeedStep(evt.message)});agentFeedStep('Dossier créé : pitch et CV ATS générés.','done');agentFeedFinish();message('Dossier créé : pitch et CV ATS générés, à vérifier avant approbation.');await Promise.all([loadApplications(),loadOverview()]);loadKanban();loadJobs();openDossier(r.id,true)}catch(e){message(e.message,'error');agentFeedStep(e.message,'error');agentFeedFinish('error')}finally{if(btn&&document.body.contains(btn)){btn.disabled=false;btn.textContent=idle}}}
let allApplications=[];let currentDossierId=null;
function dossierLabel(a){const j=a.job||{};const title=j.title||a.email_subject||'Dossier sans titre';const co=j.company?` · ${j.company}`:'';const dates=[j.created_at?`annonce ${fmtDate(j.created_at)}`:'',dossierCreatedAt(a)?`dossier ${fmtDate(dossierCreatedAt(a))}`:''].filter(Boolean);return `#${a.id} — ${title}${co}${dates.length?' · '+dates.join(' · '):''}`}
async function loadApplications(){const apps=await api('/api/applications');allApplications=apps||[];const picker=$('dossierPicker');if(picker){const prev=picker.value||String(currentDossierId||'');picker.innerHTML='<option value="">— Choisir un dossier —</option>'+allApplications.map(a=>`<option value="${a.id}">${safe(dossierLabel(a))}</option>`).join('');if(prev&&allApplications.some(a=>String(a.id)===String(prev)))picker.value=prev}
if(currentDossierId&&!allApplications.some(a=>a.id===currentDossierId))currentDossierId=null;
if(!currentDossierId&&allApplications.length)currentDossierId=allApplications[0].id;
if(picker&&currentDossierId)picker.value=String(currentDossierId);
renderDossier();renderApplicationList()}
async function scheduleFollowupThenRefresh(id){try{await api('/api/applications/'+id+'/followup',{method:'POST'});message('Relance planifiée, à approuver avant envoi.');const fresh=await api('/api/applications/'+id);const i=allApplications.findIndex(a=>a.id===id);if(i>=0)allApplications[i]=fresh;renderDossier();renderApplicationList();loadKanban()}catch(e){message(e.message,'error')}}
async function approveFollowupThenRefresh(id){try{await api('/api/applications/'+id+'/followup/approve',{method:'POST'});message('Relance approuvée.');const fresh=await api('/api/applications/'+id);const i=allApplications.findIndex(a=>a.id===id);if(i>=0)allApplications[i]=fresh;renderDossier();renderApplicationList();loadKanban()}catch(e){message(e.message,'error')}}
async function setState(id,state){try{await api('/api/applications/'+id+'/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state})});message(state==='approved'?'Candidature approuvée. Vous pouvez créer le brouillon e-mail.':'Candidature rejetée.');loadApplications()}catch(e){message(e.message,'error')}}
async function emailDraft(id){try{await api('/api/applications/'+id+'/email-draft',{method:'POST'});message('Brouillon e-mail créé. Aucun e-mail n’a été envoyé.');loadApplications()}catch(e){message(e.message,'error')}}
const KANBAN_COLUMNS=['draft','submitted','screening','interview','offer','rejected','withdrawn','closed'];
const STATUS_LABELS={draft:'Brouillon',submitted:'Envoyée',screening:'Présélection',interview:'Entretien',offer:'Offre',rejected:'Refusée',withdrawn:'Retirée',closed:'Fermée'};
/* --------------------------------------- dossier : statuts, badges, dates */
const STATE_LABELS={draft:'Brouillon',to_validate:'À valider',approved:'Approuvé',rejected:'Rejeté',email_draft_created:'Brouillon e-mail',sent:'Envoyé'};
const RELANCE_TEXT={none:'Aucune relance planifiée',pending_approval:'Relance à approuver',approved:'Relance approuvée'};
function statusBadge(status){return `<span class="badge status-${safe(status)}">${safe(STATUS_LABELS[status]||status)}</span>`}
function stateBadge(state){return `<span class="badge state-${safe(state)}">${safe(STATE_LABELS[state]||state)}</span>`}
function historyOf(a){return Array.isArray(a?.history)?a.history:[]}
function lastHistory(a,kinds){const list=kinds?historyOf(a).filter(h=>kinds.includes(h.kind)):historyOf(a);return list.length?list[list.length-1]:null}
function dossierCreatedAt(a){const entry=historyOf(a).find(h=>h.kind==='application_created');return entry?entry.at:null}
function dossierDates(a){const j=a.job||{};const moved=lastHistory(a,['status_changed','state_change','email_sent']);return [['Annonce ajoutée le',fmtDateTime(j.created_at)],['Dossier créé le',fmtDateTime(dossierCreatedAt(a))],['Dernier mouvement',moved?fmtDateTime(moved.at):'']].filter(([,v])=>v)}
function dossierDatesList(a){const rows=dossierDates(a).map(([k,v])=>`<li><strong>${safe(k)}</strong><span>${safe(v)}</span></li>`).join('');return rows?`<ul class="detail-list dossier-dates">${rows}</ul>`:''}
function timeline(a){const list=historyOf(a);if(!list.length)return '<p class="hint">Aucun événement enregistré pour ce dossier.</p>';return `<ol class="timeline">${list.map((h,i)=>`<li class="${i===list.length-1?'current':''}"><time datetime="${safe(h.at||'')}">${safe(fmtDateTime(h.at)||'date inconnue')}</time><span>${safe(h.label)}</span></li>`).join('')}</ol>`}
function relanceSummary(a){const due=fmtDate(a.followup_due_at);const base=RELANCE_TEXT[a.followup_state]||a.followup_state;return due?`${base} · échéance ${due}`:base}
function kanbanCard(c){const relance=c.followup_state==='pending_approval'?'<span class="badge warn">Relance à approuver</span>':c.followup_state==='approved'?`<span class="badge">Relance · ${safe(fmtDate(c.followup_due_at)||'sans échéance')}</span>`:'';const score=c.score!=null?` · ${c.score}/10`:'';const dates=[c.job_created_at?`annonce ${fmtDate(c.job_created_at)}`:'',c.application_created_at?`dossier ${fmtDate(c.application_created_at)}`:'',c.status_updated_at?`statut ${fmtDate(c.status_updated_at)}`:''].filter(Boolean).join(' · ');const primary=c.followup_state==='pending_approval'?`<button type="button" class="primary" onclick="approveFollowup(${c.id})">Approuver relance</button>`:`<button type="button" class="ghost" onclick="openDossier(${c.id},true)">Ouvrir le dossier</button>`;const secondary=c.followup_state==='pending_approval'?`<button type="button" class="ghost" onclick="openDossier(${c.id},true)">Ouvrir le dossier</button>`:`<button type="button" class="ghost" onclick="scheduleFollowup(${c.id})">Planifier relance</button>`;return `<article class="kanban-card clickable" draggable="true" ondragstart="kanbanDragStart(event,${c.id})" onclick="openDossier(${c.id},true)" title="Ouvrir le dossier #${c.id}"><div class="kanban-card-head"><strong>#${c.id} · ${safe(c.job_title||'Offre inconnue')}</strong><small>${safe(c.company||'Entreprise inconnue')}${c.location?' · '+safe(c.location):''}${score}</small></div>${dates?`<small class="kanban-dates">${safe(dates)}</small>`:''}${relance?`<div class="kanban-tags">${relance}</div>`:''}${c.email_subject?`<em>${safe(c.email_subject)}</em>`:''}<div class="kanban-actions" onclick="event.stopPropagation()">${secondary}${primary}</div></article>`}
let kanbanCards=[];
async function loadKanban(){try{const k=await api('/api/kanban');kanbanCards=k.cards||[];renderKanban();const r=await api('/api/report');lastReport=r;renderTrackingReport(r);renderTrackingTodo()}catch(e){message(e.message,'error')}}
let showAllKanbanColumns=false;
function renderKanban(){const activeStatuses=new Set(kanbanCards.map(card=>card.status));const columns=showAllKanbanColumns?KANBAN_COLUMNS:KANBAN_COLUMNS.filter(status=>activeStatuses.has(status));const toggle=`<button class="ghost kanban-toggle" onclick="toggleKanbanColumns()">${showAllKanbanColumns?'Masquer les étapes vides':'Afficher toutes les étapes'}</button>`;const board=columns.map(s=>{const cards=kanbanCards.filter(c=>c.status===s);return `<div class="kanban-col" data-status="${s}" ondragover="kanbanOver(event)" ondragleave="kanbanOut(event)" ondrop="kanbanDrop(event,'${s}')"><h4>${STATUS_LABELS[s]} <span class="kanban-count">${cards.length}</span></h4><div class="kanban-cards">${cards.map(kanbanCard).join('')||'<div class="kanban-empty">—</div>'}</div></div>`}).join('');$('kanbanBoard').innerHTML=toggle+`<div class="kanban-columns">${board||'<div class="empty">Aucune candidature à suivre.</div>'}</div>`}
function toggleKanbanColumns(){showAllKanbanColumns=!showAllKanbanColumns;renderKanban()}
function renderTrackingReport(report){const box=$('trackingReport');if(!box)return;if(!report?.total){box.hidden=true;return}const due=report.due_followups||0;box.hidden=false;box.innerHTML=`<strong>${report.total} candidature(s) suivie(s)</strong>${due?` · <span class="warning">${due} relance(s) à traiter</span>`:''}`}
function renderTrackingTodo(){const box=$('trackingTodo');if(!box)return;const o=lastOverview||{},rep=lastReport||{};const apps=(typeof allApplications!=='undefined'?allApplications:[])||[];const offers=o.high_score_count||0;const followups=rep.due_followups||0;const toValidate=o.to_validate_count!=null?o.to_validate_count:apps.filter(a=>a.state==='to_validate').length;const item=(n,label,onclick)=>`<button type="button" class="todo-item" onclick="${onclick}"><strong>${n}</strong><span>${label}</span></button>`;const items=[];if(offers>0)items.push(item(offers,'offre(s) à examiner',"showTab('market')"));if(followups>0)items.push(item(followups,'relance(s) à traiter',"showTab('tracking')"));if(toValidate>0)items.push(item(toValidate,'dossier(s) à valider',"showTab('applications')"));if(!items.length){box.hidden=true;box.innerHTML='';return}box.hidden=false;box.innerHTML=`<div class="todo-title">À traiter maintenant</div><div class="todo-items">${items.join('')}</div>`}
let kanbanDragId=null;
function kanbanDragStart(ev,id){kanbanDragId=id;ev.dataTransfer.effectAllowed='move';try{ev.dataTransfer.setData('text/plain',String(id))}catch(x){}}
function kanbanOver(ev){ev.preventDefault();ev.currentTarget.classList.add('over')}
function kanbanOut(ev){ev.currentTarget.classList.remove('over')}
function kanbanDrop(ev,status){ev.preventDefault();ev.currentTarget.classList.remove('over');const id=Number(ev.dataTransfer.getData('text/plain'))||kanbanDragId;moveCard(id,status)}
async function moveCard(id,status){const card=kanbanCards.find(c=>c.id===id);if(!card||card.status===status)return;const prev=card.status;card.status=status;renderKanban();try{await api(`/api/applications/${id}/status?status=${status}`,{method:'POST'});message(`Candidature #${id} : ${STATUS_LABELS[status]||status}.`);const r=await api('/api/report');renderTrackingReport(r);loadApplications()}catch(e){card.status=prev;renderKanban();message(e.message,'error')}}
async function scheduleFollowup(id){try{await api(`/api/applications/${id}/followup`,{method:'POST'});message('Relance planifiée, à approuver avant envoi.');loadKanban()}catch(e){message(e.message,'error')}}
async function approveFollowup(id){try{await api(`/api/applications/${id}/followup/approve`,{method:'POST'});message('Relance approuvée.');loadKanban()}catch(e){message(e.message,'error')}}
function goApplications(id){openDossier(id,true)}
async function openDossier(id,switchTab){if(!id)return;currentDossierId=Number(id);const picker=$('dossierPicker');if(picker)picker.value=String(currentDossierId);try{const fresh=await api('/api/applications/'+currentDossierId);const i=allApplications.findIndex(a=>a.id===currentDossierId);if(i>=0)allApplications[i]=fresh;else allApplications.unshift(fresh)}catch(e){}
if(switchTab)showTab('applications');
renderDossier();renderApplicationList();
requestAnimationFrame(()=>{const v=$('dossierView');if(v&&switchTab)v.scrollIntoView({behavior:'smooth',block:'start'})})}
function currentDossier(){return allApplications.find(a=>a.id===currentDossierId)||null}
function renderApplicationList(){const box=$('applicationList');if(!box)return;box.className='applications mini-list';box.innerHTML=allApplications.map(a=>{const j=a.job||{};const active=a.id===currentDossierId?' active':'';const moved=lastHistory(a,['status_changed','state_change','email_sent']);return `<button type="button" class="mini-card${active}" onclick="openDossier(${a.id},false)"><strong>#${a.id} · ${safe(j.title||a.email_subject||'Dossier')}</strong><small>${safe(j.company||'Entreprise inconnue')}</small><span class="mini-tags">${statusBadge(a.status)}${stateBadge(a.state)}</span><small class="hint">${[j.created_at?`annonce ${fmtDate(j.created_at)}`:'',dossierCreatedAt(a)?`dossier ${fmtDate(dossierCreatedAt(a))}`:'',moved?`statut ${fmtDate(moved.at)}`:''].filter(Boolean).join(' · ')||'dates inconnues'}</small>${a.submitted_at?`<small class="hint">envoyée le ${safe(fmtDateTime(a.submitted_at))}</small>`:''}</button>`}).join('')||'<div class="empty">Aucune candidature. Retenez d’abord une offre puis créez son dossier.</div>'}
function dossierField(id,suffix){const el=$('dossier_'+suffix+'_'+id);return el?el.value:''}
async function saveDossierSilent(id){const body={pitch:dossierField(id,'pitch'),email_subject:dossierField(id,'subject'),email_body:dossierField(id,'body'),cv_after:dossierField(id,'cv'),skills_to_highlight:dossierField(id,'skills').split(/[\n,]+/).map(s=>s.trim()).filter(Boolean)};const updated=await api('/api/applications/'+id+'/content',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const i=allApplications.findIndex(a=>a.id===id);if(i>=0)allApplications[i]=updated;return updated}
async function saveDossier(id,btn){const idle=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent='Enregistrement…'}try{await saveDossierSilent(id);renderDossier();renderApplicationList();message('Retouches enregistrées dans le dossier #'+id+'.')}catch(e){message(e.message,'error')}finally{if(btn){btn.disabled=false;btn.textContent=idle}}}
async function regenerateDossier(id,btn){const idle=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent='Régénération…'}agentFeedStart('Régénération dossier #'+id);try{const r=await streamPost('/api/applications/'+id+'/generate/stream',{method:'POST'},evt=>{if(evt.type==='progress')agentFeedStep(evt.message)});const i=allApplications.findIndex(a=>a.id===id);if(i>=0)allApplications[i]=r;agentFeedStep('Dossier régénéré.','done');agentFeedFinish();renderDossier();renderApplicationList();message('Dossier régénéré : relisez avant approbation.')}catch(e){agentFeedStep(e.message,'error');agentFeedFinish('error');message(e.message,'error')}finally{if(btn){btn.disabled=false;btn.textContent=idle}}}
async function aiRefineDossier(id,btn){const promptEl=$('dossier_ai_prompt_'+id);const targetEl=$('dossier_ai_target_'+id);const prompt=promptEl?promptEl.value:'';const target=targetEl?targetEl.value:'pitch';if(!prompt.trim()){message('Écrivez une consigne pour l’IA avant de lancer la réécriture.','error');return}const statusEl=$('dossier_ai_status_'+id);const idle=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent='Réécriture IA…'}if(statusEl)statusEl.textContent='Sauvegarde de vos textes puis réécriture IA…';try{await saveDossierSilent(id);if(statusEl)statusEl.textContent='Réécriture en cours (Rédacteur ↔ Évaluateur)…';const r=await api('/api/applications/'+id+'/refine/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({comments:prompt,document_type:target})});if(r.application){const i=allApplications.findIndex(a=>a.id===id);if(i>=0)allApplications[i]=r.application;renderDossier();renderApplicationList()}const note=(r.score!=null)?('Note évaluateur : '+Number(r.score).toFixed(1)+'/10 en '+r.iterations+' itération(s) ('+r.status+').'):'Réécriture terminée.';if(statusEl)statusEl.textContent=note+' Relisez le texte avant approbation.';message('Texte réécrit par l’IA : '+note)}catch(e){if(statusEl)statusEl.textContent='';message(e.message,'error')}finally{if(btn){btn.disabled=false;btn.textContent=idle}}}
async function moveCardDossier(id,status){try{await api('/api/applications/'+id+'/status?status='+status,{method:'POST'});message('Dossier #'+id+' : '+(STATUS_LABELS[status]||status)+'.');const fresh=await api('/api/applications/'+id);const i=allApplications.findIndex(a=>a.id===id);if(i>=0)allApplications[i]=fresh;renderDossier();renderApplicationList();loadKanban()}catch(e){message(e.message,'error')}}
/* ------------------------------------------- vue dossier (annonce + textes) */
function renderJobPanel(a,j){if(!j.title)return '<section class="dossier-panel dossier-job"><h4>Annonce visée</h4><p class="hint">Annonce introuvable pour ce dossier.</p></section>';const open=j.url?`<a class="ghost link-btn" href="${safe(j.url)}" target="_blank" rel="noopener">Ouvrir l'annonce ↗</a>`:'<small class="hint">URL absente dans la source.</small>';return `<section class="dossier-panel dossier-job"><div class="dossier-panel-head"><h4>Annonce visée</h4>${open}</div>${dossierDatesList(a)}${detailBlock(j)}${a.quality?.warnings?.length?`<small class="warning">${safe(a.quality.warnings.join(' · '))}</small>`:''}</section>`}
function renderTimelinePanel(a){return `<section class="dossier-panel dossier-timeline"><h4>Chronologie</h4>${timeline(a)}</section>`}
function renderDossierHead(a,j,sal){const title=j.title||a.email_subject||'Dossier à préparer';const meta=[j.company||'Entreprise inconnue',j.location,j.contract,sal,j.score!=null?`${j.score}/10`:''].filter(Boolean).map(safe).join(' · ');return `<div class="dossier-head"><div><span class="eyebrow">DOSSIER #${a.id}</span><h3>${safe(title)}</h3><p class="hint">${meta}</p></div><div class="dossier-head-side"><div class="dossier-badges">${stateBadge(a.state)}${statusBadge(a.status)}</div><label class="status-select"><span>Statut Kanban</span><select class="select" onchange="moveCardDossier(${a.id},this.value)">${KANBAN_COLUMNS.map(s=>`<option value="${s}" ${a.status===s?'selected':''}>${STATUS_LABELS[s]}</option>`).join('')}</select></label></div></div>`}
function renderDossierApp(a,j){const relanceBtns=a.followup_state==='pending_approval'?`<button type="button" class="primary" onclick="approveFollowupThenRefresh(${a.id})">Approuver la relance</button>`:['submitted','screening','interview'].includes(a.status)?`<button type="button" class="ghost" onclick="scheduleFollowupThenRefresh(${a.id})">Planifier une relance</button>`:'';const stateBtns=a.state==='to_validate'?`<button type="button" class="ghost" onclick="setState(${a.id},'rejected')">Rejeter</button><button type="button" class="primary" onclick="setState(${a.id},'approved')">Approuver la candidature</button>`:a.state==='approved'?`<button type="button" class="primary" onclick="emailDraft(${a.id})">Créer le brouillon e-mail</button>`:'';const summary=[relanceSummary(a),a.submitted_at?`envoyée le ${fmtDateTime(a.submitted_at)}`:''].filter(Boolean).join(' · ');return `<section class="dossier-panel dossier-app"><h4>Vos textes — réadaptables</h4><label class="field"><span>Objet e-mail</span><input id="dossier_subject_${a.id}" value=""></label><label class="field"><span>Pitch (2-4 phrases)</span><textarea id="dossier_pitch_${a.id}" rows="5"></textarea></label><label class="field"><span>E-mail de candidature</span><textarea id="dossier_body_${a.id}" rows="8"></textarea></label><label class="field"><span>CV ATS (texte)</span><textarea id="dossier_cv_${a.id}" rows="12"></textarea></label><label class="field"><span>Compétences mises en avant (une par ligne)</span><textarea id="dossier_skills_${a.id}" rows="3"></textarea></label><div class="form-actions"><button type="button" class="ghost" onclick="regenerateDossier(${a.id},this)">Régénérer (pitch + CV)</button><button type="button" class="primary" onclick="saveDossier(${a.id},this)">Enregistrer mes retouches</button></div><div class="ai-box"><h4>Prompt IA — avec l’annonce sous les yeux</h4><p class="hint">Ex : rendez le pitch plus direct et ajoutez une phrase sur la compétence clé de l’annonce. La réécriture repart de vos textes et de l’annonce affichée à gauche.</p><div class="ai-row"><select id="dossier_ai_target_${a.id}" class="select"><option value="pitch">Pitch</option><option value="cv_ats">CV ATS</option></select><input id="dossier_ai_prompt_${a.id}" placeholder="Votre consigne pour l’IA…"><button type="button" class="primary" onclick="aiRefineDossier(${a.id},this)">Compléter avec l’IA</button></div><small id="dossier_ai_status_${a.id}" class="hint"></small></div><div class="dossier-status"><p class="dossier-status-text">${safe(summary)}</p><div class="actions">${relanceBtns}${stateBtns}</div></div></section>`}
function renderDossier(){const view=$('dossierView');if(!view)return;const a=currentDossier();if(!a){view.hidden=true;view.innerHTML='';return}
const j=a.job||{};const sal=fmtSal(j.salary_min,j.salary_max);
view.hidden=false;
view.innerHTML=`<article class="card dossier-card" id="dossier_${a.id}">${renderDossierHead(a,j,sal)}<div class="dossier-grid"><div class="dossier-side">${renderJobPanel(a,j)}${renderTimelinePanel(a)}</div>${renderDossierApp(a,j)}</div></article>`;
fillDossierFields(a)}
bindJobFilters();boot()
function fillDossierFields(a){const set=(s,v)=>{const el=$(s);if(el)el.value=v||''};set('dossier_subject_'+a.id,a.email_subject);set('dossier_pitch_'+a.id,a.pitch);set('dossier_body_'+a.id,a.email_body);set('dossier_cv_'+a.id,a.cv_after);set('dossier_skills_'+a.id,(a.skills_to_highlight||[]).join('\n'));autoSizeDossierTextareas()}
